284	    private static void assertThrows(
285	        String message,
286	        Class<? extends Throwable> expectedType,
287	        ThrowingRunnable action
288	    ) {
289	        try {
290	            action.run();
291	        } catch (Throwable thrown) {
292	            if (expectedType.isInstance(thrown)) {
293	                return;
294	            }
295	
296	            throw new AssertionError(
297	                message + ": expected " + expectedType.getSimpleName()
298	                    + ", got " + thrown.getClass().getSimpleName(),
299	                thrown
300	            );
301	        }
302	
303	        throw new AssertionError(
304	            message + ": expected " + expectedType.getSimpleName() + " to be thrown"
305	        );
306	    }
